// ES: Un bucle que corre n veces hace n pasos: Θ(n).
for (let i = 0; i < n; i++) work();

// ES: Cada par (i, j) con i < j se visita una vez: n(n-1)/2 veces, o sea Θ(n²).
// Para n = 10 son 10 * 9 / 2 = 45 veces.
for (let i = 0; i < n; i++)
	for (let j = i + 1; j < n; j++) work();

// ES: i se duplica: 1, 2, 4, 8... solo unas log2(n) iteraciones: Θ(log n).
for (let i = 1; i < n; i *= 2) work();

// ES: El externo duplica i, el interno corre i veces: 1 + 2 + 4 + ... + n es unas 2n: Θ(n).
for (let i = 1; i < n; i *= 2)
	for (let j = 0; j < i; j++) work();

// ES: El interno salta de i en i: n/1 + n/2 + n/3 + ... es unas n log n: Θ(n log n).
for (let i = 1; i <= n; i++)
	for (let j = 0; j < n; j += i) work();

// ES: Invariante: cuando corre la prueba i < n, s es la suma de a[0..i-1].
// Inicio: i = 0, s = 0 (suma vacía). Mantenimiento: sumar a[i] da la suma de a[0..i].
// Final: i = n, así que s es la suma de todo el arreglo.
let s = 0;
for (let i = 0; i < a.length; i++) s += a[i];

// ES: Cada llamada espera a la siguiente, así que se apilan n marcos: espacio O(n).
// (Sin optimización de llamada en cola, que la mayoría de los lenguajes no garantiza.)
function sum(n: number): number {
	if (n === 0) return 0;
	return n + sum(n - 1);
}
